//go:build arm64

package floats

// The NEON kernels of the MDCT fold and unfold (fold.go), generated by go-asmgen
// (fold_arm64_gen.go) into fold_arm64.s: two float64 per step. A kernel does the
// floor(h/2) steps that fit and the Go code finishes the rest. NEON is the ARMv8-A
// baseline: no gate. No kernel keeps a pointer: go:noescape.
//
//go:noescape
func mdctFold64NEON(dst, x []float64)

//go:noescape
func mdctFoldFrom32NEON(dst []float64, x []float32)

//go:noescape
func mdctUnfold64NEON(dst, u []float64)

//go:noescape
func mdctUnfoldTo32NEON(dst []float32, u []float64)

func mdctFold(dst, x []float64) {
	mdctFold64NEON(dst, x)
	foldTail(dst, x, (len(x)/4)&^1)
}

func mdctFold32(dst []float64, x []float32) {
	mdctFoldFrom32NEON(dst, x)
	fold32Tail(dst, x, (len(x)/4)&^1)
}

func mdctUnfold(dst, u []float64) {
	mdctUnfold64NEON(dst, u)
	unfoldTail(dst, u, (len(u)/2)&^1)
}

func mdctUnfold32(dst []float32, u []float64) {
	mdctUnfoldTo32NEON(dst, u)
	unfold32Tail(dst, u, (len(u)/2)&^1)
}
